from collections import deque
edges = [
    ("user:kim", "MemberOf", "group:HelpDesk"),
    ("group:HelpDesk", "AdminTo", "pc:WS-042"),
    ("pc:WS-042", "HasSession", "user:adm_lee"),
    ("user:adm_lee", "MemberOf", "group:Domain Admins"),
    ("user:park", "MemberOf", "group:Sales"),
]
g = {}
for s, r, d in edges:
    g.setdefault(s, []).append((r, d))
def path(src, dst):
    q, seen = deque([(src, [])]), {src}
    while q:
        n, p = q.popleft()
        if n == dst:
            return p
        for r, d in g.get(n, []):
            if d not in seen:
                seen.add(d); q.append((d, p + [f"{n} -{r}-> {d}"]))
for who in ["user:kim", "user:park"]:
    p = path(who, "group:Domain Admins")
    print(who, "->", "경로 없음" if p is None else f"{len(p)}단계")
    for step in p or []:
        print("   ", step)
# user:kim -> 4단계
#     user:kim -MemberOf-> group:HelpDesk
#     group:HelpDesk -AdminTo-> pc:WS-042
#     pc:WS-042 -HasSession-> user:adm_lee
#     user:adm_lee -MemberOf-> group:Domain Admins
# user:park -> 경로 없음

tier_acct = {"adm_lee": 0, "srv_ops": 1, "kim": 2}
tier_host = {"DC01": 0, "APP01": 1, "WS-042": 2}
logons = [("adm_lee", "DC01"), ("adm_lee", "WS-042"), ("srv_ops", "APP01"), ("kim", "WS-042")]
for a, h in logons:
    ta, th = tier_acct[a], tier_host[h]
    print(f"{a}(T{ta}) -> {h}(T{th})", "위반" if ta < th else "정상")
